package com.saumya.pos.fulfillment;
import com.saumya.pos.AuthorizationTestSecurityConfiguration;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.test.web.servlet.MockMvc;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(controllers={VendorShipmentController.class,CustomerShipmentController.class}) @Import(AuthorizationTestSecurityConfiguration.class)
class ShipmentControllerAuthorizationTest {
 @Autowired MockMvc mvc;@MockBean ShipmentService service;
 @Test @WithMockUser(authorities={"SHIPMENT_VIEW"}) void vendorViewCanReadQueue() throws Exception{when(service.eligibleOrders()).thenReturn(List.of());mvc.perform(get("/api/v1/vendor/shipments/orders")).andExpect(status().isOk());}
 @Test @WithMockUser(authorities={"POS_VIEW"}) void posViewDoesNotGrantShipmentView() throws Exception{mvc.perform(get("/api/v1/vendor/shipments")).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test @WithMockUser(authorities={"SHIPMENT_UPDATE"}) void shipmentUpdateCanCreateAndAppend() throws Exception{when(service.createShipment(anyString(),anyString(),anyString(),any(),anyString())).thenReturn(null);mvc.perform(post("/api/v1/vendor/orders/order-1/shipments").contentType("application/json").content("{\"carrier\":\"Carrier\",\"trackingReference\":\"T-1\",\"reason\":\"Create shipment\"}")).andExpect(status().isCreated());}
 @Test @WithMockUser(authorities={"CUSTOMER"}) void customerActorCanReadOwnShipmentRoute() throws Exception{when(service.customerShipments(anyString(),anyString())).thenReturn(List.of());mvc.perform(get("/api/v1/customer/orders/order-1/shipments")).andExpect(status().isOk());}
 @Test @WithMockUser(authorities={"SHIPMENT_VIEW"}) void vendorCannotUseCustomerRoute() throws Exception{mvc.perform(get("/api/v1/customer/orders/order-1/shipments")).andExpect(status().isForbidden());verifyNoInteractions(service);}
}
